// frontend/utils/profileEditPermissions.ts
import type { UserRole } from '~/client';

export type ProfileEditMode = 'self' | 'admin';

const CANVASSER_ROLES: UserRole[] = ['canvasser', 'subcontractor_canvasser'];

/**
 * Bio text is editable in every case EXCEPT a canvasser / subcontractor_canvasser
 * editing their own profile (they may regenerate the bio, but not hand-edit it).
 */
export function canEditBioText(mode: ProfileEditMode, editorRole: UserRole | undefined): boolean {
  if (mode === 'admin') return true;
  if (!editorRole) return false;
  return !CANVASSER_ROLES.includes(editorRole);
}

/**
 * Manage = edit or clear a profile. An admin may manage any profile EXCEPT another
 * admin's — but always their own. This is the single source of truth shared by the
 * user-details card and the admin edit page so the button gating and the route guard
 * can never diverge.
 */
export function canAdminManageProfile(targetRole: UserRole, isOwnProfile: boolean): boolean {
  return targetRole !== 'admin' || isOwnProfile;
}
